const NOTES=[{title:'NEW TOKENS (TK B in sododeck-cards.js) AND DATABASE PARTS',items:[['tblW 240','Table default width. 240 fits a 19-character name and an 11-character type at Geist 12 / Mono 11.'],['colH 24','Column row height, fixed. Anchor y = top + 24 i + 12, top = 1.5 + 12 + 24 + 8 + 18 + note + 8.'],['colMax 12','Row limit. Order when cut: PK, FK, rest; a row with a connector always stays, so a cut table can show more than 12.'],['Show all / Show fewer','Dashed 1.5 Border-strong button, full card width minus 24, 24 tall, radius 8, Geist 11.5 / 500 Secondary: “Show all 60 columns” / “Show fewer”. 6 above it. Per table, saved in the deck. A hidden column’s connector anchors at the button centre.'],['colInset 4 · keyW 16','Row fill inset 4, radius 8; key slot 16 (30 when any row carries two markers). Glyphs: PK key-round, FK link-2, unique “U” square, nullable “?” in a 7px slot.'],['R / W markers','16 × 16, radius 5, Mono 9.5 / 600 at the row end: W = Deck Orange fill, Ink text; R = 1.5px orange outline, Orange Ink text. The letter carries the meaning; the row gets Orange Soft. Shown only during flow playback.'],['Dialect chip','B neutral chip (21 tall, Surface 2, database icon 12, 11.5 / 500) in the database card’s header badge slot. Read-only; the dialect is set once per deck in the Deck settings drawer.'],['crowLen 12 · crowSpread 6 · crowBar 16 · crowRing 4','Toes ±6 from the edge to 12 out; bar at 10 (one), 8 (zero-or-one), 16 (one-or-many); ring r4 filled with Canvas.'],['Header type name','“Table · public”, “Table · auth” when the deck has more than one schema (Shop does: users is in auth); “Table” in a one-schema deck.']]},
 {title:'REUSED UNCHANGED FROM sododeck-canvas.js (AND sododeck-states.js)',items:[['Shell','base() root, dot grid and theme variables; chrome(): deck island (≡, name 500, save icon, views control), tools island (Jump to, Labels, Focus, theme, Export), rail (select, add, sticky, group, connector, Outline, Flows, Rules, Search) with its own badge for Problems, undo / redo island, zoom island, minimap.'],['Panels','flyout(), drawer() + dHead(), secR() sections with LAB() labels, tbar() selection toolbar with ib() / dv() / SW() cells, menu() context menus and submenus, popP() popovers, tip() tooltips, pill() hints, panel() / row() / cell().'],['Controls','PRIM (primary, 34 / 32), SEC (secondary), inp (36 inputs and selects), chip / addChip, TXT. Toggle and segmented control as in sododeck-states.js (I.toggle 32 × 18, segI 26). Dialogs: the states dialog (420–840 wide, 20 radius, 20 padding, header icon + 13.5 / 500 title + 12 sub, buttons right) over the standard scrim.'],['Step player','The canvas-first player panel: 32px SEC / PRIM buttons, “Step n of 8 · title” over “from → to”, 1× pill, 4px progress segments. Stickers, lip and token stay on board B cards.'],['Toasts','The existing Undo toast: inverse pill 40 tall, underlined Undo button, ⌘Z hint, 6 s.'],['Added, not restyled','Names · Keys · All as segmented cells inside the zoom island; a breadcrumb island under the deck island when inside a database.']]},
 {title:'DECK SETTINGS = DETAILS DRAWER IN DECK MODE',items:[['Open','≡ menu: All decks · Import… · Export… · Deck settings · Show JSON · Dark mode · Keyboard shortcuts. Deck settings opens the right drawer (360) in deck mode; no modal.'],['Header','dHead: layers tile, “Shop”, subtitle “Deck”, close.'],['Sections','Problems (amber row, arrow) · Name · Description (markdown, Write / Preview) · Tags · Summary (components, connections, flows + Rules tile) · Database · Storage.'],['Database','Dialect select (Generic, Postgres, MySQL, SQLite, a one-line hint each) · Notation (Crow’s foot / 1 / n) · Show on tables: data types, nullable marker, notes, index footer · Show on relationships: cardinality ends, labels (Follow Labels / Hover / Always / Off) · Export: block SQL export with errors.'],['Dialect change','Confirm dialog listing the converted columns, then the Undo toast. Database cards show the dialect as a read-only chip; their drawer says “Postgres · set in Deck settings”.']]},
 {title:'CANVAS 2D',items:[['Table','B card rects (fill, 1.5 stroke, 3px lip as an offset rect, 14 radius) and a fixed list of text runs; row i at y = top + 24 i + 12. Text ellipsis from measureText, cached per string.'],['Rows','Hover / highlight / problem / R-W: roundRect inset 4, radius 8. Selected / target: same rect stroked 2px orange. Markers: one 16px roundRect + one Mono glyph.'],['Crow’s foot','u = end tangent (side normal for curved and elbow, line angle for straight), v ⟂ u. Toes: p+6v → p+12u → p−6v; bar across at a; ring arc r4 filled Canvas then stroked; round joins and caps.'],['Composite key','6px stub per member row, one vertical joining segment, the connector leaves its midpoint.']]},
 {title:'RISKS',items:[['Dense schemas','40+ tables at All is a wall of text; Keys and groups by schema keep it readable; Focus keeps one hop.'],['Long tables','Cutting at 12 hides columns people look for: in-table search and Jump to by column are required. Show all on several 60-column tables makes the board very tall.'],['Wide types','Types cut first (≤ 58 % of the row), then names. Converting dialect lengthens types (char(36), datetime(6)).'],['Connector clutter','Row anchors fan many lines into one edge; two-key pairs stay two lines; ×n bundling only where rows are not drawn.'],['Anchors when cut','Hidden columns anchor on the Show all button, which becomes a hot spot; connected rows are kept, so a cut table can exceed 12.'],['Collapsed / System','At Keys every connector still has a row; at System and Landscape connectors go table to table from the title row and merge ×n. Changing detail re-flows heights; tables keep their top-left.']]}];

